bool CodeValue::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("code_id"))
    {
        if(!validJsonOfField(1, "code_id", pJson["code_id"], err, true))
            return false;
    }
    else
    {
        err="The code_id column cannot be null";
        return false;
    }
    if(pJson.isMember("code_value"))
    {
        if(!validJsonOfField(2, "code_value", pJson["code_value"], err, true))
            return false;
    }
    if(pJson.isMember("code_description"))
    {
        if(!validJsonOfField(3, "code_description", pJson["code_description"], err, true))
            return false;
    }
    if(pJson.isMember("order_position"))
    {
        if(!validJsonOfField(4, "order_position", pJson["order_position"], err, true))
            return false;
    }
    if(pJson.isMember("code_score"))
    {
        if(!validJsonOfField(5, "code_score", pJson["code_score"], err, true))
            return false;
    }
    if(pJson.isMember("is_active"))
    {
        if(!validJsonOfField(6, "is_active", pJson["is_active"], err, true))
            return false;
    }
    if(pJson.isMember("is_mandatory"))
    {
        if(!validJsonOfField(7, "is_mandatory", pJson["is_mandatory"], err, true))
            return false;
    }
    return true;
}
